package com.codex.loginsight;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class CodexLogInsightPluginRunner
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(CodexLogInsightPlugin.class);
		RuneLite.main(args);
	}
}

package com.codex.loginsight;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(CodexLogInsightConfig.GROUP)
public interface CodexLogInsightConfig extends Config
{
	String GROUP = "codexloginsight";

	enum Rates
	{
		AUTO("Match my account"),
		MAIN("Normal account"),
		IRON("Ironman");

		private final String label;

		Rates(String label)
		{
			this.label = label;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	@ConfigSection(
		name = "New slots",
		description = "What Log Insight does when a new collection log slot drops",
		position = 0
	)
	String finds = "finds";

	@ConfigSection(
		name = "Estimates",
		description = "How Log Insight estimates time",
		position = 1
	)
	String estimates = "estimates";

	@ConfigItem(
		keyName = "showPlaque",
		name = "Show plaque",
		description = "Show a plaque in the game view with the slot's odds and how lucky it was",
		position = 1,
		section = finds
	)
	default boolean showPlaque()
	{
		return true;
	}

	@Range(min = 3, max = 30)
	@Units(Units.SECONDS)
	@ConfigItem(
		keyName = "plaqueSeconds",
		name = "Plaque time",
		description = "How long the plaque stays up",
		position = 2,
		section = finds
	)
	default int plaqueSeconds()
	{
		return 8;
	}

	@ConfigItem(
		keyName = "chatLine",
		name = "Luck in chat",
		description = "Add a line to the chat box saying how lucky each new slot was",
		position = 3,
		section = finds
	)
	default boolean chatLine()
	{
		return true;
	}

	@ConfigItem(
		keyName = "rates",
		name = "Rates",
		description = "Typical kills per hour for a normal account or an ironman",
		position = 1,
		section = estimates
	)
	default Rates rates()
	{
		return Rates.AUTO;
	}

	@ConfigItem(
		keyName = "learnPace",
		name = "Learn my pace",
		description = "Time your kill counts and use your own pace once Log Insight has seen enough of them",
		position = 2,
		section = estimates
	)
	default boolean learnPace()
	{
		return true;
	}
}

package com.codex.loginsight;

import com.codex.loginsight.core.Analyst;
import com.codex.loginsight.core.ChatReader;
import com.codex.loginsight.core.LogStructure;
import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Progress;
import com.codex.loginsight.core.Report;
import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import com.codex.loginsight.overlay.FindPlaque;
import com.codex.loginsight.ui.Format;
import com.codex.loginsight.ui.ItemIcons;
import com.codex.loginsight.ui.LogInsightPanel;
import com.codex.loginsight.ui.Sigil;
import com.codex.loginsight.ui.Theme;
import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.inject.Provides;
import java.awt.Color;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.ScriptEvent;
import net.runelite.api.ScriptID;
import net.runelite.api.StructComposition;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "Codex Log Insight",
	description = "Collection log analytics: your luck at your kill counts, time left on each page and the fastest slots to chase",
	tags = {"collection", "log", "clog", "luck", "dry", "drop", "rate", "pet", "codex"}
)
public class CodexLogInsightPlugin extends Plugin
{
	private static final String PROGRESS_KEY = "progress";
	/** The script that sends the client every owned slot when the log's Search is opened. */
	private static final int COLLECTION_TRANSMIT = 4100;
	/** Enum of the log's tabs; each tab struct points to its pages, each page to its slots. */
	private static final int TAB_ENUM = 2102;
	private static final int TAB_PAGES_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_PARAM = 690;
	/** Slots whose id the log swaps for a stand-in, mapping the stand-in back. */
	private static final int REPLACEMENT_ENUM = 3721;
	private static final String[] TAB_NAMES = {"Bosses", "Raids", "Clues", "Minigames", "Other"};
	private static final int TRANSMIT_SETTLE_TICKS = 3;
	private static final int SAVE_TICKS = 100;
	private static final int ANALYSE_GAP_TICKS = 2;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private Gson gson;

	@Inject
	private CodexLogInsightConfig config;

	private final FindPlaque plaque = new FindPlaque();
	private final AtomicInteger generation = new AtomicInteger();
	private final Set<Integer> harvest = new HashSet<>();
	private final Map<Integer, Integer> replacements = new HashMap<>();

	private LogData data;
	private Analyst analyst;
	private ChatReader chat;
	private LogInsightPanel panel;
	private NavigationButton navButton;

	private LogStructure structure = LogStructure.empty();
	private Progress progress;
	private String profile;
	private boolean dirty;
	private boolean unsaved;
	private int ticksSinceSave;
	private int ticksSinceAnalysis;
	private int lastTransmitTick = -1;
	private int officialOwned = -1;
	private int officialTotal = -1;

	@Provides
	CodexLogInsightConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexLogInsightConfig.class);
	}

	@Override
	protected void startUp() throws IOException
	{
		data = LogData.load(gson);
		analyst = new Analyst(data);
		chat = new ChatReader(data.getLabels());
		ItemIcons icons = (itemId, onLoaded) ->
		{
			AsyncBufferedImage image = itemManager.getImage(itemId);
			image.onLoaded(onLoaded);
			return image;
		};
		panel = new LogInsightPanel(icons);
		navButton = NavigationButton.builder()
			.tooltip("Codex Log Insight")
			.icon(Sigil.icon(16))
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		clientThread.invokeLater(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadProgress();
				buildStructure();
				dirty = true;
			}
		});
	}

	@Override
	protected void shutDown()
	{
		clientThread.invokeLater(() ->
		{
			save();
			progress = null;
			profile = null;
		});
		overlayManager.remove(plaque);
		clientToolbar.removeNavigation(navButton);
		plaque.clear();
		generation.incrementAndGet();
		structure = LogStructure.empty();
		harvest.clear();
		lastTransmitTick = -1;
		panel = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			harvest.clear();
			lastTransmitTick = -1;
		}
		if (event.getGameState() == GameState.LOGIN_SCREEN)
		{
			save();
			progress = null;
			profile = null;
			officialOwned = -1;
			officialTotal = -1;
			plaque.clear();
			publish(Report.loggedOut(), null);
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		progress = null;
		loadProgress();
		dirty = true;
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!CodexLogInsightConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		if (!config.showPlaque())
		{
			plaque.clear();
		}
		dirty = true;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (progress == null)
		{
			loadProgress();
			dirty |= progress != null;
		}
		if (structure.isEmpty())
		{
			buildStructure();
			dirty |= !structure.isEmpty();
		}
		if (lastTransmitTick >= 0 && client.getTickCount() - lastTransmitTick > TRANSMIT_SETTLE_TICKS)
		{
			finishFullRead();
		}

		int owned = client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
		int total = client.getVarpValue(VarPlayerID.COLLECTION_COUNT_MAX);
		if (total > 0 && (owned != officialOwned || total != officialTotal))
		{
			officialOwned = owned;
			officialTotal = total;
			dirty = true;
		}

		ticksSinceAnalysis++;
		if (dirty && ticksSinceAnalysis >= ANALYSE_GAP_TICKS)
		{
			dirty = false;
			ticksSinceAnalysis = 0;
			analyse();
		}
		if (unsaved && ++ticksSinceSave >= SAVE_TICKS)
		{
			save();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		if (event.getScriptId() != COLLECTION_TRANSMIT || progress == null || isAnotherPlayersLog())
		{
			return;
		}
		ScriptEvent script = event.getScriptEvent();
		Object[] args = script == null ? null : script.getArguments();
		if (args == null || args.length < 3 || !(args[1] instanceof Integer) || !(args[2] instanceof Integer))
		{
			return;
		}
		int itemId = (Integer) args[1];
		int quantity = (Integer) args[2];
		if (itemId > 0 && quantity > 0)
		{
			harvest.add(replacements.getOrDefault(itemId, itemId));
			lastTransmitTick = client.getTickCount();
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() == ScriptID.COLLECTION_DRAW_LIST)
		{
			// The page's header and slots are filled in after the script returns.
			clientThread.invokeLater(this::readOpenPage);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		ChatMessageType type = event.getType();
		if (progress == null || type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.FRIENDSCHATNOTIFICATION)
		{
			return;
		}
		String message = event.getMessage();
		ChatReader.Count count = chat.count(message);
		if (count != null && count.value >= 0)
		{
			progress.setCounter(count.label, count.value);
			if (config.learnPace())
			{
				progress.paceFor(count.label).record(count.value, System.currentTimeMillis());
			}
			changed();
			return;
		}
		String slot = ChatReader.newSlot(message);
		if (slot != null)
		{
			onNewSlot(slot);
		}
	}

	/** Reads the page open in the collection log: its counters and which slots are owned. */
	private void readOpenPage()
	{
		if (progress == null || isAnotherPlayersLog())
		{
			return;
		}
		Widget header = client.getWidget(InterfaceID.Collection.HEADER_TEXT);
		Widget[] lines = header == null ? null : header.getDynamicChildren();
		if (lines == null || lines.length == 0 || lines[0] == null)
		{
			return;
		}
		String page = Text.removeTags(lines[0].getText()).trim();
		if (page.isEmpty())
		{
			return;
		}
		List<String> labels = new ArrayList<>();
		for (int i = 1; i < lines.length; i++)
		{
			ChatReader.Count counter = lines[i] == null ? null : ChatReader.pageCounter(lines[i].getText());
			if (counter != null)
			{
				labels.add(counter.label);
				progress.setCounter(counter.label, counter.value);
			}
		}
		Widget items = client.getWidget(InterfaceID.Collection.ITEMS);
		Widget[] slots = items == null ? null : items.getDynamicChildren();
		if (slots != null)
		{
			for (Widget slot : slots)
			{
				// The log draws owned slots solid and missing ones faded.
				if (slot != null && slot.getItemId() > 0 && slot.getOpacity() == 0)
				{
					progress.addOwned(replacements.getOrDefault(slot.getItemId(), slot.getItemId()));
				}
			}
		}
		progress.setPageLabels(page, labels);
		progress.markPageRead(page, System.currentTimeMillis());
		changed();
	}

	private void finishFullRead()
	{
		lastTransmitTick = -1;
		if (progress == null || harvest.isEmpty())
		{
			harvest.clear();
			return;
		}
		for (int id : harvest)
		{
			progress.addOwned(id);
		}
		harvest.clear();
		progress.setFullReadAt(System.currentTimeMillis());
		changed();
		save();
	}

	private void onNewSlot(String name)
	{
		List<Integer> ids = structure.idsNamed(name);
		int itemId = -1;
		for (int id : ids)
		{
			if (!progress.owns(id))
			{
				itemId = id;
				break;
			}
		}
		if (itemId < 0 && !ids.isEmpty())
		{
			itemId = ids.get(0);
		}

		ItemOdds odds = itemId > 0 ? data.odds(itemId) : null;
		String label = null;
		int count = 0;
		double chance = 0;
		double luckier = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			Integer value = progress.counter(label);
			count = value == null ? 0 : value;
			chance = odds.mainChance();
			luckier = odds.dryChance(progress.getCounters());
		}
		else if (itemId > 0)
		{
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				chance = Math.max(chance, 1 / Math.max(1, drop.getAttempts()));
			}
		}
		List<LogStructure.Page> pages = itemId > 0 ? structure.pagesOf(itemId) : java.util.Collections.emptyList();
		String page = pages.isEmpty() ? null : pages.get(0).getName();
		if (itemId > 0)
		{
			progress.addOwned(itemId);
		}
		progress.addFind(new Progress.Find(itemId, name, page, label, count, chance, luckier, System.currentTimeMillis()));
		changed();
		save();

		String odd = chance > 0 ? Format.chance(chance) + (count > 0 ? " at " + Format.count(count) + " " + Format.counterName(label) + " kc" : "") : page;
		String verdict = luckier >= 0 ? "Luckier than " + Math.round(luckier * 100) + "% of players" : null;
		Color color = luckier >= 0 ? Theme.luck(Luck.verdict(luckier)) : Theme.GOLD;
		if (config.showPlaque())
		{
			plaque.show(new FindPlaque.View(name, page, odd, verdict, color, itemId > 0 && data.isPet(itemId),
				itemId > 0 ? itemManager.getImage(itemId) : null, System.currentTimeMillis(), config.plaqueSeconds() * 1000L));
		}
		if (config.chatLine() && (chance > 0 || verdict != null))
		{
			ChatMessageBuilder line = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Log Insight: ")
				.append(ChatColorType.NORMAL).append(name);
			if (odd != null)
			{
				line.append(", " + odd);
			}
			if (verdict != null)
			{
				line.append(". ").append(ChatColorType.HIGHLIGHT).append(verdict).append(ChatColorType.NORMAL);
			}
			line.append(".");
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(line.build())
				.build());
		}
	}

	private void changed()
	{
		dirty = true;
		unsaved = true;
	}

	private boolean isAnotherPlayersLog()
	{
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private boolean ironRates()
	{
		switch (config.rates())
		{
			case IRON:
				return true;
			case MAIN:
				return false;
			default:
				return client.getVarbitValue(VarbitID.IRONMAN) != 0;
		}
	}

	/** Reads the log's tabs, pages and slots from the game cache. */
	private void buildStructure()
	{
		EnumComposition tabEnum = client.getEnum(TAB_ENUM);
		int[] tabStructs = tabEnum == null ? null : tabEnum.getIntVals();
		if (tabStructs == null || tabStructs.length == 0)
		{
			return;
		}
		replacements.clear();
		EnumComposition swap = client.getEnum(REPLACEMENT_ENUM);
		if (swap != null)
		{
			int[] keys = swap.getKeys();
			int[] values = swap.getIntVals();
			for (int i = 0; i < Math.min(keys.length, values.length); i++)
			{
				replacements.put(keys[i], values[i]);
			}
		}

		List<LogStructure.Tab> tabs = new ArrayList<>();
		Map<Integer, String> names = new HashMap<>();
		for (int t = 0; t < tabStructs.length; t++)
		{
			StructComposition tabStruct = client.getStructComposition(tabStructs[t]);
			EnumComposition pageEnum = tabStruct == null ? null : client.getEnum(tabStruct.getIntValue(TAB_PAGES_PARAM));
			if (pageEnum == null)
			{
				continue;
			}
			String tabName = t < TAB_NAMES.length ? TAB_NAMES[t] : "Tab " + (t + 1);
			List<LogStructure.Page> pages = new ArrayList<>();
			for (int pageStructId : pageEnum.getIntVals())
			{
				StructComposition pageStruct = client.getStructComposition(pageStructId);
				EnumComposition itemEnum = pageStruct == null ? null : client.getEnum(pageStruct.getIntValue(PAGE_ITEMS_PARAM));
				if (itemEnum == null)
				{
					continue;
				}
				List<Integer> items = new ArrayList<>();
				for (int raw : itemEnum.getIntVals())
				{
					int id = replacements.getOrDefault(raw, raw);
					items.add(id);
					names.computeIfAbsent(id, k -> Text.removeTags(itemManager.getItemComposition(k).getName()));
				}
				pages.add(new LogStructure.Page(tabName, pageStruct.getStringValue(PAGE_NAME_PARAM), items));
			}
			tabs.add(new LogStructure.Tab(tabName, pages));
		}
		structure = new LogStructure(tabs, names);
		log.debug("Collection log read: {} tabs, {} slots", tabs.size(), structure.getUniqueSlots());
	}

	private void loadProgress()
	{
		String key = configManager.getRSProfileKey();
		if (key == null)
		{
			return;
		}
		profile = key;
		Progress loaded = null;
		String json = configManager.getRSProfileConfiguration(CodexLogInsightConfig.GROUP, PROGRESS_KEY);
		if (json != null && !json.isEmpty())
		{
			try
			{
				loaded = gson.fromJson(json, Progress.class);
			}
			catch (JsonParseException e)
			{
				log.warn("Could not read saved collection log progress, starting fresh", e);
			}
		}
		progress = loaded == null ? new Progress() : loaded;
		seedFromChatCommands();
	}

	/** Fills counters the log has not shown yet from the kill counts RuneLite's chat commands remember. */
	private void seedFromChatCommands()
	{
		for (String label : data.getLabels())
		{
			if (progress.counter(label) != null)
			{
				continue;
			}
			Integer count = configManager.getRSProfileConfiguration("killcount", ChatReader.base(label), Integer.class);
			if (count != null && count > 0)
			{
				progress.setCounter(label, count);
			}
		}
	}

	private void save()
	{
		ticksSinceSave = 0;
		if (progress == null || profile == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexLogInsightConfig.GROUP, profile, PROGRESS_KEY, gson.toJson(progress));
	}

	private void analyse()
	{
		if (progress == null)
		{
			publish(Report.loggedOut(), null);
			return;
		}
		Progress snapshot = progress.copy();
		LogStructure shape = structure;
		boolean iron = ironRates();
		boolean pace = config.learnPace();
		int owned = officialOwned;
		int total = officialTotal;
		Player player = client.getLocalPlayer();
		String name = player == null ? null : player.getName();
		int ticket = generation.incrementAndGet();
		executor.execute(() ->
		{
			try
			{
				Report report = analyst.analyse(shape, snapshot, iron, pace, owned, total);
				if (ticket == generation.get())
				{
					publish(report, name);
				}
			}
			catch (RuntimeException e)
			{
				log.warn("Log Insight analysis failed", e);
			}
		});
	}

	private void publish(Report report, String name)
	{
		LogInsightPanel target = panel;
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(report, name));
		}
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import com.codex.loginsight.data.ItemOdds;
import com.codex.loginsight.data.LogData;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Turns the log's shape, the bundled rates and this account's progress into a Report.
 * Pure Java over immutable inputs, so it runs off the client thread and is tested
 * without a game.
 */
public final class Analyst
{
	/** Kill count gaps needed before your own pace replaces the typical rate. */
	static final int PACE_SAMPLES = 15;
	private static final int DRIEST = 6;
	private static final double DRY_SHOWN_BELOW = 0.35;

	private final LogData data;
	/** The counter each activity advances, when its slots agree on one. */
	private final Map<Integer, String> activityLabels = new HashMap<>();

	public Analyst(LogData data)
	{
		this.data = data;
		for (Activity activity : data.getActivities())
		{
			Map<String, Integer> votes = new HashMap<>();
			for (Activity.Drop drop : activity.getDrops())
			{
				ItemOdds odds = data.odds(drop.getItemId());
				if (odds != null)
				{
					votes.merge(odds.mainLabel(), 1, Integer::sum);
				}
			}
			votes.entrySet().stream()
				.max(Map.Entry.comparingByValue())
				.filter(e -> e.getValue() * 2 >= activity.getDrops().size())
				.ifPresent(e -> activityLabels.put(activity.getIndex(), e.getKey()));
		}
	}

	/**
	 * @param ownPace use the pace learned from your kill counts where there is enough of it
	 */
	public Report analyse(LogStructure structure, Progress progress, boolean iron, boolean ownPace, int officialOwned,
		int officialTotal)
	{
		Rates rates = new Rates(progress, iron, ownPace);
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();

		List<Report.PageReport> pages = new ArrayList<>();
		Set<Integer> unique = new LinkedHashSet<>();
		int complete = 0;
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				Report.PageReport report = page(structure, page, progress, rates);
				pages.add(report);
				if (report.isComplete())
				{
					complete++;
				}
				unique.addAll(page.getItems());
			}
		}

		int knownOwned = 0;
		List<Integer> missing = new ArrayList<>();
		for (int id : unique)
		{
			if (owned.contains(id))
			{
				knownOwned++;
			}
			else
			{
				missing.add(id);
			}
		}

		Finish finish = finish(missing, owned, rates);
		Luck luck = luck(unique, owned, counters);
		List<Report.ItemReport> driest = driest(structure, missing, progress, rates);
		List<Report.Hunt> hunts = hunts(structure, owned, rates);

		return new Report(true, !structure.isEmpty(), officialOwned, officialTotal, knownOwned, unique.size(),
			progress.getFullReadAt(), progress.pagesReadCount(), pages.size(), complete, luck, finish.hours,
			finish.unrated, iron, pages, hunts, driest, progress.getFinds());
	}

	/** Builds the report for one slot, for the panel and for the drop plaque. */
	public Report.ItemReport item(LogStructure structure, int itemId, String page, Progress progress, boolean iron)
	{
		return item(structure, itemId, page, progress, new Rates(progress, iron, true));
	}

	private Report.PageReport page(LogStructure structure, LogStructure.Page page, Progress progress, Rates rates)
	{
		Set<Integer> owned = progress.getOwned();
		Map<String, Integer> counters = progress.getCounters();
		List<Report.ItemReport> items = new ArrayList<>();
		List<Integer> missing = new ArrayList<>();
		Map<String, Integer> labelVotes = new LinkedHashMap<>();
		int ownedCount = 0;
		for (int id : page.getItems())
		{
			items.add(item(structure, id, page.getName(), progress, rates));
			if (owned.contains(id))
			{
				ownedCount++;
			}
			else
			{
				missing.add(id);
			}
			ItemOdds odds = data.odds(id);
			if (odds != null)
			{
				for (ItemOdds.Roll roll : odds.getRolls())
				{
					labelVotes.merge(roll.getLabel(), roll.getLabel().equals(odds.mainLabel()) ? 2 : 1, Integer::sum);
				}
			}
		}

		String mainLabel = labelVotes.entrySet().stream()
			.max(Map.Entry.comparingByValue())
			.map(Map.Entry::getKey)
			.orElse(null);
		List<String> shownLabels = progress.pageLabels(page.getName());
		if (shownLabels == null)
		{
			shownLabels = new ArrayList<>(labelVotes.keySet());
		}
		List<String> lines = new ArrayList<>();
		for (String label : shownLabels)
		{
			Integer value = counters.get(label);
			if (value != null)
			{
				lines.add(label + ": " + String.format("%,d", value));
			}
		}
		if (mainLabel == null && !shownLabels.isEmpty())
		{
			mainLabel = shownLabels.get(0);
		}
		Integer count = mainLabel == null ? null : counters.get(mainLabel);

		Finish finish = finish(missing, owned, rates);
		Next next = next(missing, owned, rates);
		Luck luck = luck(page.getItems(), owned, counters);
		return new Report.PageReport(page.getTab(), page.getName(), ownedCount, page.getItems().size(), lines,
			count == null ? -1 : count, mainLabel, luck, finish.hours, next.hours, next.source, finish.unrated,
			progress.isPageRead(page.getName()), items);
	}

	private Report.ItemReport item(LogStructure structure, int id, String page, Progress progress, Rates rates)
	{
		ItemOdds odds = data.odds(id);
		double chance = 0;
		String label = null;
		int count = -1;
		double dry = -1;
		if (odds != null)
		{
			label = odds.mainLabel();
			chance = odds.mainChance();
			Integer value = progress.counter(label);
			count = value == null ? -1 : value;
			dry = odds.dryChance(progress.getCounters());
		}
		Activity.Drop fastest = rates.fastest(id);
		String source = null;
		double hours = Double.POSITIVE_INFINITY;
		if (fastest != null)
		{
			Activity activity = data.activity(fastest.getActivityIndex());
			source = activity.getName();
			hours = rates.hours(activity, fastest.getAttempts());
			if (chance == 0)
			{
				chance = 1 / fastest.getAttempts();
			}
		}
		return new Report.ItemReport(id, structure.name(id), page, progress.owns(id), data.isPet(id), chance, label,
			count, dry, source, hours);
	}

	private Luck luck(Collection<Integer> items, Set<Integer> owned, Map<String, Integer> counters)
	{
		List<Double> chances = new ArrayList<>();
		int have = 0;
		Set<Integer> seen = new HashSet<>();
		for (int id : items)
		{
			if (!seen.add(id))
			{
				continue;
			}
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double dry = odds.dryChance(counters);
			if (dry < 0)
			{
				continue;
			}
			chances.add(1 - dry);
			if (owned.contains(id))
			{
				have++;
			}
		}
		if (chances.isEmpty())
		{
			return null;
		}
		double[] array = new double[chances.size()];
		for (int i = 0; i < array.length; i++)
		{
			array[i] = chances.get(i);
		}
		return Luck.of(array, have);
	}

	private List<Report.ItemReport> driest(LogStructure structure, List<Integer> missing, Progress progress, Rates rates)
	{
		List<Report.ItemReport> dry = new ArrayList<>();
		for (int id : missing)
		{
			ItemOdds odds = data.odds(id);
			if (odds == null)
			{
				continue;
			}
			double chance = odds.dryChance(progress.getCounters());
			if (chance >= 0 && chance < DRY_SHOWN_BELOW)
			{
				List<LogStructure.Page> pages = structure.pagesOf(id);
				dry.add(item(structure, id, pages.isEmpty() ? null : pages.get(0).getName(), progress, rates));
			}
		}
		dry.sort(Comparator.comparingDouble(Report.ItemReport::getDryChance));
		return dry.size() > DRIEST ? new ArrayList<>(dry.subList(0, DRIEST)) : dry;
	}

	private List<Report.Hunt> hunts(LogStructure structure, Set<Integer> owned, Rates rates)
	{
		Set<Integer> inLog = new HashSet<>();
		for (LogStructure.Tab tab : structure.getTabs())
		{
			for (LogStructure.Page page : tab.getPages())
			{
				inLog.addAll(page.getItems());
			}
		}
		List<Report.Hunt> hunts = new ArrayList<>();
		for (Activity activity : data.getActivities())
		{
			double perHour = rates.perHour(activity);
			if (perHour <= 0)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, id -> inLog.isEmpty() || inLog.contains(id));
			if (eval.remaining == 0 || Double.isInfinite(eval.nextAttempts))
			{
				continue;
			}
			boolean pet = false;
			for (int id : eval.missing)
			{
				pet |= data.isPet(id);
			}
			hunts.add(new Report.Hunt(activity.getName(), activity.getCategory(),
				rates.hoursFor(activity, eval.nextAttempts), rates.hoursFor(activity, eval.allAttempts), eval.remaining,
				eval.nextItem, eval.nextItem < 0 ? null : structure.name(eval.nextItem), eval.nextChance, eval.nextExact, perHour,
				rates.isOwnPace(activity), pet, eval.missing));
		}
		hunts.sort(Comparator.comparingDouble(Report.Hunt::getHoursToNext));
		return hunts;
	}

	/** Hours to finish these slots, each hunted at its fastest source. */
	private Finish finish(List<Integer> missing, Set<Integer> owned, Rates rates)
	{
		Map<Integer, Set<Integer>> byActivity = new LinkedHashMap<>();
		int unrated = 0;
		for (int id : missing)
		{
			Activity.Drop fastest = rates.fastest(id);
			if (fastest == null)
			{
				unrated++;
				continue;
			}
			byActivity.computeIfAbsent(fastest.getActivityIndex(), k -> new HashSet<>()).add(id);
		}
		double hours = 0;
		for (Map.Entry<Integer, Set<Integer>> e : byActivity.entrySet())
		{
			Activity activity = data.activity(e.getKey());
			Eval eval = evaluate(activity, owned, e.getValue()::contains);
			hours += rates.hoursFor(activity, eval.allAttempts);
		}
		return new Finish(byActivity.isEmpty() ? (unrated > 0 ? Double.POSITIVE_INFINITY : 0) : hours, unrated);
	}

	/** The soonest new slot among these, from any activity that drops one. */
	private Next next(List<Integer> missing, Set<Integer> owned, Rates rates)
	{
		Set<Integer> wanted = new HashSet<>(missing);
		Set<Integer> activities = new LinkedHashSet<>();
		for (int id : missing)
		{
			for (Activity.Drop drop : data.dropsOf(id))
			{
				activities.add(drop.getActivityIndex());
			}
		}
		double best = Double.POSITIVE_INFINITY;
		String source = null;
		for (int index : activities)
		{
			Activity activity = data.activity(index);
			if (rates.perHour(activity) <= 0)
			{
				continue;
			}
			Eval eval = evaluate(activity, owned, wanted::contains);
			double hours = rates.hoursFor(activity, eval.nextAttempts);
			if (hours < best)
			{
				best = hours;
				source = activity.getName();
			}
		}
		return new Next(best, source);
	}

	/**
	 * Walks an activity's table in order. A slot can roll when it is missing and, if it
	 * only drops after the slot before it, that slot is owned.
	 */
	private Eval evaluate(Activity activity, Set<Integer> owned, java.util.function.IntPredicate include)
	{
		Eval eval = new Eval();
		double chanceSum = 0;
		double exactNext = Double.POSITIVE_INFINITY;
		double bestChance = 0;
		List<Double> chains = new ArrayList<>();
		List<Double> exactChains = new ArrayList<>();
		boolean previousOwned = false;
		boolean previousOpen = false;
		boolean previousExact = false;
		Set<Integer> counted = new HashSet<>();
		for (Activity.Drop drop : activity.getDrops())
		{
			int id = drop.getItemId();
			boolean has = owned.contains(id);
			if (!has && include.test(id))
			{
				if (counted.add(id))
				{
					eval.missing.add(id);
				}
				boolean canRoll = !drop.isSequential() || previousOwned;
				if (canRoll)
				{
					if (drop.isExact())
					{
						exactNext = Math.min(exactNext, drop.getAttempts());
					}
					else
					{
						double chance = 1 / Math.max(1, drop.getAttempts());
						chanceSum += chance;
						if (chance > bestChance)
						{
							bestChance = chance;
							eval.nextItem = id;
						}
					}
				}
				List<Double> target = drop.isExact() ? exactChains : chains;
				if (drop.isSequential() && previousOpen && previousExact == drop.isExact() && !target.isEmpty())
				{
					target.set(target.size() - 1, target.get(target.size() - 1) + drop.getAttempts());
				}
				else
				{
					target.add(drop.getAttempts());
				}
				previousOpen = true;
				previousExact = drop.isExact();
			}
			else
			{
				previousOpen = false;
			}
			previousOwned = has;
		}
		if (Double.isFinite(exactNext) && (eval.nextItem < 0 || exactNext < 1 / chanceSum))
		{
			for (Activity.Drop drop : activity.getDrops())
			{
				if (drop.isExact() && drop.getAttempts() == exactNext && eval.missing.contains(drop.getItemId()))
				{
					eval.nextItem = drop.getItemId();
					eval.nextExact = true;
					bestChance = 1 / Math.max(1, exactNext);
					break;
				}
			}
		}
		double exactAll = 0;
		for (double c : exactChains)
		{
			exactAll = Math.max(exactAll, c);
		}
		double[] rolled = new double[chains.size()];
		for (int i = 0; i < rolled.length; i++)
		{
			rolled[i] = chains.get(i);
		}
		eval.remaining = eval.missing.size();
		eval.nextChance = bestChance;
		eval.nextAttempts = eval.remaining == 0 ? Double.POSITIVE_INFINITY : Odds.attemptsToNext(chanceSum, exactNext);
		eval.allAttempts = eval.remaining == 0 ? 0 : Odds.attemptsToAll(rolled, exactAll);
		return eval;
	}

	/** Completions per hour for each activity: your own pace where it is known, the typical rate otherwise. */
	private final class Rates
	{
		private final Progress progress;
		private final boolean iron;
		private final boolean ownPace;
		private final Map<Integer, Activity.Drop> fastest = new HashMap<>();

		Rates(Progress progress, boolean iron, boolean ownPace)
		{
			this.progress = progress;
			this.iron = iron;
			this.ownPace = ownPace;
		}

		boolean isOwnPace(Activity activity)
		{
			if (!ownPace)
			{
				return false;
			}
			String label = activityLabels.get(activity.getIndex());
			Progress.Pace pace = label == null ? null : progress.pace(label);
			return pace != null && pace.getSamples() >= PACE_SAMPLES && pace.perHour() > 0;
		}

		double perHour(Activity activity)
		{
			if (isOwnPace(activity))
			{
				return progress.pace(activityLabels.get(activity.getIndex())).perHour();
			}
			return activity.perHour(iron);
		}

		double hours(Activity activity, double attempts)
		{
			return hoursFor(activity, attempts);
		}

		double hoursFor(Activity activity, double attempts)
		{
			double perHour = perHour(activity);
			if (perHour <= 0 || Double.isInfinite(attempts))
			{
				return Double.POSITIVE_INFINITY;
			}
			return attempts / perHour + activity.getSetupHours();
		}

		/** The source that gives this slot soonest on its own, or null. */
		Activity.Drop fastest(int itemId)
		{
			if (fastest.containsKey(itemId))
			{
				return fastest.get(itemId);
			}
			Activity.Drop best = null;
			double bestHours = Double.POSITIVE_INFINITY;
			for (Activity.Drop drop : data.dropsOf(itemId))
			{
				double hours = hoursFor(data.activity(drop.getActivityIndex()), drop.getAttempts());
				if (hours < bestHours)
				{
					bestHours = hours;
					best = drop;
				}
			}
			fastest.put(itemId, best);
			return best;
		}
	}

	private static final class Eval
	{
		final List<Integer> missing = new ArrayList<>();
		int remaining;
		int nextItem = -1;
		/** The next slot is earned after a fixed number of attempts rather than rolled. */
		boolean nextExact;
		double nextChance;
		double nextAttempts;
		double allAttempts;
	}

	private static final class Finish
	{
		final double hours;
		final int unrated;

		Finish(double hours, int unrated)
		{
			this.hours = hours;
			this.unrated = unrated;
		}
	}

	private static final class Next
	{
		final double hours;
		final String source;

		Next(double hours, String source)
		{
			this.hours = hours;
			this.source = source;
		}
	}
}

package com.codex.loginsight.core;

import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.util.Text;

/** Reads the game messages that move the collection log: new slots and kill counts. */
public final class ChatReader
{
	private static final Pattern NEW_SLOT = Pattern.compile("New item added to your collection log: (.+)");
	// The same shape RuneLite's chat commands read, so every boss, raid and minigame count is caught.
	private static final Pattern COUNT = Pattern.compile(
		"Your (?<pre>completion count for |subdued |completed )?(?<name>.+?) (?<post>(?:(?:kill|harvest|lap|completion|success|chest|opened) )?(?:count )?)is: ?(?<count>[0-9,]+)");
	private static final Pattern CLUES = Pattern.compile("You have completed (?<count>[0-9,]+) (?<tier>beginner|easy|medium|hard|elite|master) Treasure Trails?", Pattern.CASE_INSENSITIVE);
	private static final Pattern SUFFIX = Pattern.compile(" (kills|completions|completion count|opened|chests opened|kill count|count)$", Pattern.CASE_INSENSITIVE);

	/** Chat names that differ from the counter the collection log shows. */
	private static final Map<String, String> ALIASES = new HashMap<>();

	static
	{
		ALIASES.put("barrows", "Barrows Chests opened");
		ALIASES.put("barrows chest", "Barrows Chests opened");
		ALIASES.put("barrows chests", "Barrows Chests opened");
		ALIASES.put("lunar chest", "Lunar Chests opened");
		ALIASES.put("lunar chests", "Lunar Chests opened");
		ALIASES.put("gauntlet", "Gauntlet completion count");
		ALIASES.put("corrupted gauntlet", "Corrupted Gauntlet completion count");
		ALIASES.put("theatre of blood: hard mode", "Theatre of Blood (Hard) completions");
		ALIASES.put("theatre of blood: entry mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("theatre of blood: story mode", "Theatre of Blood (Entry) completions");
		ALIASES.put("tombs of amascut: expert mode", "Tombs of Amascut (Expert) completions");
		ALIASES.put("tombs of amascut: entry mode", "Tombs of Amascut (Entry) completions");
		ALIASES.put("chambers of xeric challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("chambers of xeric: challenge mode", "Chambers of Xeric (CM) completions");
		ALIASES.put("the leviathan", "Leviathan kills");
		ALIASES.put("the whisperer", "Whisperer kills");
		ALIASES.put("the nightmare", "Nightmare kills");
		ALIASES.put("the hueycoatl", "Hueycoatl kills");
		ALIASES.put("tztok-jad", "TzTok-Jad kills");
		ALIASES.put("tzkal-zuk", "TzKal-Zuk kills");
		ALIASES.put("wintertodt", "Wintertodt kills");
		ALIASES.put("hespori", "Hespori kills");
	}

	private final Map<String, String> labelsByBase = new HashMap<>();

	/** @param labels every counter name the odds use */
	public ChatReader(List<String> labels)
	{
		for (String label : labels)
		{
			labelsByBase.put(base(label), label);
		}
	}

	/** The item name of a "New item added" message, or null. */
	public static String newSlot(String message)
	{
		Matcher m = NEW_SLOT.matcher(Text.removeTags(message));
		return m.find() ? m.group(1).trim() : null;
	}

	private static final Pattern PAGE_COUNTER = Pattern.compile("^(?<label>[^:]+?):\\s*(?<count>[0-9,]+)$");

	/** A counter line from a collection log page header, such as "Vorkath kills: 312", or null. */
	public static Count pageCounter(String line)
	{
		Matcher m = PAGE_COUNTER.matcher(Text.removeTags(line).trim());
		if (!m.find())
		{
			return null;
		}
		int value = parse(m.group("count"));
		return value < 0 ? null : new Count(m.group("label").trim(), value);
	}

	/** A kill count message read as a collection log counter, or null. */
	public Count count(String message)
	{
		String text = Text.removeTags(message);
		Matcher clue = CLUES.matcher(text);
		if (clue.find())
		{
			String tier = clue.group("tier");
			String label = Character.toUpperCase(tier.charAt(0)) + tier.substring(1).toLowerCase(Locale.ENGLISH) + " clues completed";
			return new Count(label, parse(clue.group("count")));
		}
		Matcher m = COUNT.matcher(text);
		if (!m.find())
		{
			return null;
		}
		String name = m.group("name").trim();
		String label = labelFor(name);
		return label == null ? null : new Count(label, parse(m.group("count")));
	}

	/** The counter a chat name refers to, or null if the log has no such counter. */
	String labelFor(String chatName)
	{
		String key = chatName.trim().toLowerCase(Locale.ENGLISH);
		String alias = ALIASES.get(key);
		if (alias != null)
		{
			return alias;
		}
		String label = labelsByBase.get(key);
		if (label == null && key.startsWith("the "))
		{
			label = labelsByBase.get(key.substring(4));
		}
		return label;
	}

	/** "Vorkath kills" to "vorkath", the key RuneLite's chat commands save counts under. */
	public static String base(String label)
	{
		return SUFFIX.matcher(label.trim()).replaceFirst("").toLowerCase(Locale.ENGLISH);
	}

	private static int parse(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	public static final class Count
	{
		public final String label;
		public final int value;

		Count(String label, int value)
		{
			this.label = label;
			this.value = value;
		}
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/**
 * The shape of the collection log as the game defines it: tabs, their pages and the
 * slots on each page, with item names. Read from the game cache once per session, so
 * new pages and slots appear without a plugin update.
 */
public final class LogStructure
{
	@Getter
	private final List<Tab> tabs;
	private final Map<Integer, String> names;
	private final Map<String, List<Integer>> idsByName;
	private final Map<Integer, List<Page>> pagesByItem;
	@Getter
	private final int uniqueSlots;

	public LogStructure(List<Tab> tabs, Map<Integer, String> names)
	{
		this.tabs = Collections.unmodifiableList(new ArrayList<>(tabs));
		this.names = Collections.unmodifiableMap(new HashMap<>(names));
		Map<String, List<Integer>> byName = new HashMap<>();
		Map<Integer, List<Page>> byItem = new HashMap<>();
		Set<Integer> unique = new LinkedHashSet<>();
		for (Tab tab : this.tabs)
		{
			for (Page page : tab.getPages())
			{
				for (int id : page.getItems())
				{
					unique.add(id);
					byItem.computeIfAbsent(id, k -> new ArrayList<>()).add(page);
				}
			}
		}
		for (int id : unique)
		{
			byName.computeIfAbsent(key(name(id)), k -> new ArrayList<>()).add(id);
		}
		this.idsByName = byName;
		this.pagesByItem = byItem;
		this.uniqueSlots = unique.size();
	}

	public static LogStructure empty()
	{
		return new LogStructure(Collections.emptyList(), Collections.emptyMap());
	}

	public boolean isEmpty()
	{
		return tabs.isEmpty();
	}

	public String name(int itemId)
	{
		String name = names.get(itemId);
		return name == null ? "Item " + itemId : name;
	}

	/** Slots with this exact name; several when variants share one, such as coloured ornaments. */
	public List<Integer> idsNamed(String name)
	{
		List<Integer> ids = idsByName.get(key(name));
		return ids == null ? Collections.emptyList() : ids;
	}

	public List<Page> pagesOf(int itemId)
	{
		List<Page> pages = pagesByItem.get(itemId);
		return pages == null ? Collections.emptyList() : pages;
	}

	public Page page(String name)
	{
		for (Tab tab : tabs)
		{
			for (Page page : tab.getPages())
			{
				if (page.getName().equalsIgnoreCase(name))
				{
					return page;
				}
			}
		}
		return null;
	}

	private static String key(String name)
	{
		return name.trim().toLowerCase(Locale.ENGLISH);
	}

	@Getter
	public static final class Tab
	{
		private final String name;
		private final List<Page> pages;

		public Tab(String name, List<Page> pages)
		{
			this.name = name;
			this.pages = Collections.unmodifiableList(new ArrayList<>(pages));
		}
	}

	@Getter
	public static final class Page
	{
		private final String tab;
		private final String name;
		private final List<Integer> items;

		public Page(String tab, String name, List<Integer> items)
		{
			this.tab = tab;
			this.name = name;
			this.items = Collections.unmodifiableList(new ArrayList<>(items));
		}
	}
}

package com.codex.loginsight.core;

import lombok.Getter;

/** How a set of slots compares with everyone else at the same counts. */
@Getter
public final class Luck
{
	public enum Verdict
	{
		PARCHED("Parched"),
		DRY("Dry"),
		EVEN("Even"),
		FORTUNATE("Fortunate"),
		BLESSED("Blessed");

		@Getter
		private final String label;

		Verdict(String label)
		{
			this.label = label;
		}
	}

	/** 0 is the driest account possible, 1 the luckiest. */
	private final double percentile;
	/** Slots an average player would own by now. */
	private final double expected;
	private final int owned;
	/** How many slots the read covers. */
	private final int slots;

	public Luck(double percentile, double expected, int owned, int slots)
	{
		this.percentile = percentile;
		this.expected = expected;
		this.owned = owned;
		this.slots = slots;
	}

	public static Luck of(double[] chances, int owned)
	{
		double expected = 0;
		for (double c : chances)
		{
			expected += c;
		}
		return new Luck(Odds.luckPercentile(chances, owned), expected, owned, chances.length);
	}

	public Verdict verdict()
	{
		return verdict(percentile);
	}

	public static Verdict verdict(double percentile)
	{
		if (percentile >= 0.85)
		{
			return Verdict.BLESSED;
		}
		if (percentile >= 0.65)
		{
			return Verdict.FORTUNATE;
		}
		if (percentile > 0.35)
		{
			return Verdict.EVEN;
		}
		return percentile > 0.15 ? Verdict.DRY : Verdict.PARCHED;
	}

	/** Whole percent of players this account is luckier than. */
	public int luckierThan()
	{
		return (int) Math.round(percentile * 100);
	}
}

package com.codex.loginsight.core;

/**
 * The probability behind every number Log Insight shows. Kept free of game types so
 * it can be tested on its own.
 */
public final class Odds
{
	private static final int STEPS = 1600;

	private Odds()
	{
	}

	/**
	 * Where an account sits among everyone at the same counts, from 0 (driest) to 1
	 * (luckiest): the share of players who would own fewer of these slots, counting
	 * half of those who own exactly as many.
	 *
	 * @param chances each slot's chance of being owned by now
	 * @param owned   how many of those slots are owned
	 */
	public static double luckPercentile(double[] chances, int owned)
	{
		int n = chances.length;
		if (n == 0)
		{
			return 0.5;
		}
		// Distribution of the number of owned slots (Poisson binomial), built one slot at a time.
		double[] dist = new double[n + 1];
		dist[0] = 1;
		for (int i = 0; i < n; i++)
		{
			double q = clamp(chances[i]);
			for (int k = i + 1; k >= 1; k--)
			{
				dist[k] = dist[k] * (1 - q) + dist[k - 1] * q;
			}
			dist[0] *= 1 - q;
		}
		owned = Math.max(0, Math.min(n, owned));
		double below = 0;
		for (int k = 0; k < owned; k++)
		{
			below += dist[k];
		}
		return Math.max(0, Math.min(1, below + dist[owned] / 2));
	}

	/**
	 * Expected attempts until any one of these slots drops.
	 *
	 * @param chanceSum the summed chance per attempt of the slots that can roll
	 * @param exact     attempts until a slot that is earned outright, or infinity
	 */
	public static double attemptsToNext(double chanceSum, double exact)
	{
		if (chanceSum <= 0)
		{
			return exact;
		}
		if (chanceSum >= 1)
		{
			return 1;
		}
		double rate = -Math.log1p(-chanceSum);
		if (Double.isInfinite(exact))
		{
			return 1 / chanceSum;
		}
		// The roll and the fixed count race; whichever comes first ends the wait.
		return (1 - Math.exp(-rate * exact)) / rate;
	}

	/**
	 * Expected attempts until every one of these slots is owned: the expected maximum of
	 * one waiting time per slot, integrated numerically.
	 *
	 * @param attempts average attempts per drop for each slot that is rolled
	 * @param exact    attempts until the last slot that is earned outright, or 0
	 */
	public static double attemptsToAll(double[] attempts, double exact)
	{
		int n = attempts.length;
		if (n == 0)
		{
			return exact;
		}
		double[] rates = new double[n];
		double slowest = 0;
		for (int i = 0; i < n; i++)
		{
			double p = clamp(1 / Math.max(1, attempts[i]));
			rates[i] = p >= 1 ? 50 : -Math.log1p(-p);
			slowest = Math.max(slowest, 1 / rates[i]);
		}
		// Past this point the chance of still missing a slot is negligible.
		double end = Math.max(exact, slowest * (Math.log(n) + 14));
		double h = end / STEPS;
		double total = 0;
		double previous = missing(rates, 0, exact);
		for (int s = 1; s <= STEPS; s++)
		{
			double t = s * h;
			double current = missing(rates, t, exact);
			total += (previous + current) / 2 * h;
			previous = current;
		}
		return Math.max(total, exact);
	}

	/** The chance that at time t some slot is still missing. */
	private static double missing(double[] rates, double t, double exact)
	{
		if (t < exact)
		{
			return 1;
		}
		double all = 1;
		for (double rate : rates)
		{
			all *= -Math.expm1(-rate * t);
		}
		return 1 - all;
	}

	private static double clamp(double p)
	{
		return Math.max(0, Math.min(1, p));
	}
}

package com.codex.loginsight.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * What this account has done, saved per RuneScape profile: owned slots, the
 * collection log's counters, the finds Log Insight saw happen and your own pace.
 * Plain fields so Gson can save it as it is.
 */
public final class Progress
{
	private static final int MAX_FINDS = 40;

	/** Slots known to be owned. Only ever grows; the game never takes a slot back. */
	private Set<Integer> owned = new HashSet<>();
	/** Collection log counters, such as "Vorkath kills" to 312. */
	private Map<String, Integer> counters = new HashMap<>();
	/** Finds seen as they happened, newest first. */
	private List<Find> finds = new ArrayList<>();
	/** Your own pace per counter. */
	private Map<String, Pace> pace = new HashMap<>();
	/** When the whole log was last read from the game, or 0. */
	private long fullReadAt;
	/** Pages whose counters were read from the log itself. */
	private Map<String, Long> pagesRead = new LinkedHashMap<>();
	/** The counter names each read page shows, in its own order. */
	private Map<String, List<String>> pageLabels = new HashMap<>();

	public Progress copy()
	{
		Progress p = new Progress();
		p.owned = new HashSet<>(owned());
		p.counters = new HashMap<>(counters());
		p.finds = new ArrayList<>(finds());
		p.pace = new HashMap<>();
		for (Map.Entry<String, Pace> e : pace().entrySet())
		{
			p.pace.put(e.getKey(), e.getValue().copy());
		}
		p.fullReadAt = fullReadAt;
		p.pagesRead = new LinkedHashMap<>(pagesRead());
		p.pageLabels = new HashMap<>(pageLabels());
		return p;
	}

	// Gson leaves fields null when an older save lacks them, so every read goes through these.

	private Set<Integer> owned()
	{
		if (owned == null)
		{
			owned = new HashSet<>();
		}
		return owned;
	}

	private Map<String, Integer> counters()
	{
		if (counters == null)
		{
			counters = new HashMap<>();
		}
		return counters;
	}

	private List<Find> finds()
	{
		if (finds == null)
		{
			finds = new ArrayList<>();
		}
		return finds;
	}

	private Map<String, Pace> pace()
	{
		if (pace == null)
		{
			pace = new HashMap<>();
		}
		return pace;
	}

	private Map<String, Long> pagesRead()
	{
		if (pagesRead == null)
		{
			pagesRead = new LinkedHashMap<>();
		}
		return pagesRead;
	}

	private Map<String, List<String>> pageLabels()
	{
		if (pageLabels == null)
		{
			pageLabels = new HashMap<>();
		}
		return pageLabels;
	}

	public boolean owns(int itemId)
	{
		return owned().contains(itemId);
	}

	public Set<Integer> getOwned()
	{
		return Collections.unmodifiableSet(owned());
	}

	/** @return true if this slot is new */
	public boolean addOwned(int itemId)
	{
		return owned().add(itemId);
	}

	public Map<String, Integer> getCounters()
	{
		return Collections.unmodifiableMap(counters());
	}

	public Integer counter(String label)
	{
		return counters().get(label);
	}

	/** @return true if the value changed */
	public boolean setCounter(String label, int value)
	{
		Integer old = counters().put(label, value);
		return old == null || old != value;
	}

	public List<Find> getFinds()
	{
		return Collections.unmodifiableList(finds());
	}

	public void addFind(Find find)
	{
		finds().add(0, find);
		while (finds().size() > MAX_FINDS)
		{
			finds().remove(finds().size() - 1);
		}
	}

	public Pace pace(String label)
	{
		return pace().get(label);
	}

	public Pace paceFor(String label)
	{
		return pace().computeIfAbsent(label, k -> new Pace());
	}

	public long getFullReadAt()
	{
		return fullReadAt;
	}

	public void setFullReadAt(long fullReadAt)
	{
		this.fullReadAt = fullReadAt;
	}

	public void markPageRead(String page, long at)
	{
		pagesRead().put(page, at);
	}

	public void setPageLabels(String page, List<String> labels)
	{
		pageLabels().put(page, new ArrayList<>(labels));
	}

	/** Counter names the page showed when it was last read, or null. */
	public List<String> pageLabels(String page)
	{
		List<String> labels = pageLabels().get(page);
		return labels == null ? null : Collections.unmodifiableList(labels);
	}

	public int pagesReadCount()
	{
		return pagesRead().size();
	}

	public boolean isPageRead(String page)
	{
		return pagesRead().containsKey(page);
	}

	/** A slot that arrived while Log Insight was watching. */
	public static final class Find
	{
		private int itemId;
		private String name;
		private String page;
		private String label;
		private int count;
		private double chance;
		/** Share of players who would still be waiting at this count: higher is luckier. */
		private double luckier;
		private long at;

		public Find(int itemId, String name, String page, String label, int count, double chance, double luckier, long at)
		{
			this.itemId = itemId;
			this.name = name;
			this.page = page;
			this.label = label;
			this.count = count;
			this.chance = chance;
			this.luckier = luckier;
			this.at = at;
		}

		public int getItemId()
		{
			return itemId;
		}

		public String getName()
		{
			return name;
		}

		public String getPage()
		{
			return page;
		}

		public String getLabel()
		{
			return label;
		}

		/** Kill count when it dropped, or 0 if unknown. */
		public int getCount()
		{
			return count;
		}

		/** Chance per count, or 0 if unknown. */
		public double getChance()
		{
			return chance;
		}

		/** 0 to 1, or -1 if unknown. */
		public double getLuckier()
		{
			return luckier;
		}

		public long getAt()
		{
			return at;
		}
	}

	/**
	 * Your own speed at one counter, learned from the gaps between kill count messages.
	 * Gaps longer than a break are ignored so banking trips count but logging off does not.
	 */
	public static final class Pace
	{
		static final long MAX_GAP_MS = 12 * 60_000L;
		private static final double WEIGHT = 0.12;

		private double secondsPerCount;
		private int samples;
		private long lastAt;
		private int lastCount;

		Pace copy()
		{
			Pace p = new Pace();
			p.secondsPerCount = secondsPerCount;
			p.samples = samples;
			p.lastAt = lastAt;
			p.lastCount = lastCount;
			return p;
		}

		public void record(int count, long at)
		{
			if (lastAt > 0 && count > lastCount && at > lastAt && at - lastAt <= MAX_GAP_MS * (count - lastCount))
			{
				double seconds = (at - lastAt) / 1000.0 / (count - lastCount);
				secondsPerCount = samples == 0 ? seconds : secondsPerCount + (seconds - secondsPerCount) * WEIGHT;
				samples++;
			}
			lastAt = at;
			lastCount = count;
		}

		public int getSamples()
		{
			return samples;
		}

		/** Completions per hour, or 0 if not learned yet. */
		public double perHour()
		{
			return samples == 0 || secondsPerCount <= 0 ? 0 : 3600 / secondsPerCount;
		}
	}
}

package com.codex.loginsight.core;

import com.codex.loginsight.data.Activity;
import java.util.Collections;
import java.util.List;
import lombok.Getter;

/** Everything the panel shows, computed in one pass and handed over as a read-only value. */
@Getter
public final class Report
{
	private final boolean loggedIn;
	private final boolean structureLoaded;
	/** Owned slots according to the game's own counter, or -1. */
	private final int officialOwned;
	private final int officialTotal;
	/** Owned slots Log Insight can name. */
	private final int knownOwned;
	private final int totalSlots;
	private final long fullReadAt;
	private final int pagesRead;
	private final int pagesTotal;
	private final int pagesComplete;
	private final Luck luck;
	/** Hours to finish every slot that has rates, at your rates. */
	private final double hoursLeft;
	/** Missing slots without rates (bought, rewarded or unmodelled). */
	private final int unratedMissing;
	private final boolean ironRates;
	private final List<PageReport> pages;
	private final List<Hunt> hunts;
	private final List<ItemReport> driest;
	private final List<Progress.Find> finds;

	public Report(boolean loggedIn, boolean structureLoaded, int officialOwned, int officialTotal, int knownOwned,
		int totalSlots, long fullReadAt, int pagesRead, int pagesTotal, int pagesComplete, Luck luck, double hoursLeft,
		int unratedMissing, boolean ironRates, List<PageReport> pages, List<Hunt> hunts, List<ItemReport> driest,
		List<Progress.Find> finds)
	{
		this.loggedIn = loggedIn;
		this.structureLoaded = structureLoaded;
		this.officialOwned = officialOwned;
		this.officialTotal = officialTotal;
		this.knownOwned = knownOwned;
		this.totalSlots = totalSlots;
		this.fullReadAt = fullReadAt;
		this.pagesRead = pagesRead;
		this.pagesTotal = pagesTotal;
		this.pagesComplete = pagesComplete;
		this.luck = luck;
		this.hoursLeft = hoursLeft;
		this.unratedMissing = unratedMissing;
		this.ironRates = ironRates;
		this.pages = Collections.unmodifiableList(pages);
		this.hunts = Collections.unmodifiableList(hunts);
		this.driest = Collections.unmodifiableList(driest);
		this.finds = Collections.unmodifiableList(finds);
	}

	public static Report loggedOut()
	{
		return new Report(false, false, -1, -1, 0, 0, 0, 0, 0, 0, null, Double.POSITIVE_INFINITY, 0, false,
			Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), Collections.emptyList());
	}

	/** The owned count to show: the game's own when it has sent one. */
	public int owned()
	{
		return officialOwned >= 0 ? Math.max(officialOwned, knownOwned) : knownOwned;
	}

	public int total()
	{
		return officialTotal > 0 ? officialTotal : totalSlots;
	}

	/** True when Log Insight knows fewer slots than the game says you own. */
	public boolean needsFullRead()
	{
		return officialOwned > knownOwned || fullReadAt == 0 && knownOwned == 0;
	}

	/** One slot as Log Insight sees it. */
	@Getter
	public static final class ItemReport
	{
		private final int itemId;
		private final String name;
		private final String page;
		private final boolean owned;
		private final boolean pet;
		/** Chance per count of the main counter, or 0 when unknown. */
		private final double chance;
		/** The counter the chance refers to, or null. */
		private final String label;
		/** Count so far on that counter, or -1. */
		private final int count;
		/** Chance of still being without it at these counts, or -1. */
		private final double dryChance;
		/** Where it comes fastest, or null. */
		private final String source;
		/** Expected hours to get it alone from its fastest source, or infinity. */
		private final double hours;

		public ItemReport(int itemId, String name, String page, boolean owned, boolean pet, double chance, String label,
			int count, double dryChance, String source, double hours)
		{
			this.itemId = itemId;
			this.name = name;
			this.page = page;
			this.owned = owned;
			this.pet = pet;
			this.chance = chance;
			this.label = label;
			this.count = count;
			this.dryChance = dryChance;
			this.source = source;
			this.hours = hours;
		}
	}

	/** One page of the log. */
	@Getter
	public static final class PageReport
	{
		private final String tab;
		private final String name;
		private final int owned;
		private final int total;
		/** Counter lines in the order the page shows them, such as "Vorkath kills: 312". */
		private final List<String> counters;
		/** The page's main counter value, or -1. */
		private final int count;
		private final String countLabel;
		/** Null when no slot on the page has odds and a known count. */
		private final Luck luck;
		/** Expected hours to finish the slots with rates, or infinity. */
		private final double hoursToFinish;
		/** Expected hours to the next new slot, or infinity. */
		private final double hoursToNext;
		private final String nextSource;
		/** Missing slots without rates. */
		private final int unrated;
		private final boolean read;
		private final List<ItemReport> items;

		public PageReport(String tab, String name, int owned, int total, List<String> counters, int count,
			String countLabel, Luck luck, double hoursToFinish, double hoursToNext, String nextSource, int unrated,
			boolean read, List<ItemReport> items)
		{
			this.tab = tab;
			this.name = name;
			this.owned = owned;
			this.total = total;
			this.counters = Collections.unmodifiableList(counters);
			this.count = count;
			this.countLabel = countLabel;
			this.luck = luck;
			this.hoursToFinish = hoursToFinish;
			this.hoursToNext = hoursToNext;
			this.nextSource = nextSource;
			this.unrated = unrated;
			this.read = read;
			this.items = Collections.unmodifiableList(items);
		}

		public boolean isComplete()
		{
			return total > 0 && owned >= total;
		}

		public double progress()
		{
			return total == 0 ? 0 : owned / (double) total;
		}
	}

	/** One activity ranked by how soon it gives a new slot. */
	@Getter
	public static final class Hunt
	{
		private final String name;
		private final Activity.Category category;
		private final double hoursToNext;
		private final double hoursToFinish;
		private final int remaining;
		/** The slot most likely to come next. */
		private final int nextItemId;
		private final String nextItemName;
		/** Chance per attempt of the most likely next slot. */
		private final double nextChance;
		/** True when the next slot is earned after a set number of attempts, such as points or permits. */
		private final boolean nextEarned;
		private final double perHour;
		/** True when the rate is your own measured pace rather than a typical one. */
		private final boolean ownPace;
		private final boolean pet;
		private final List<Integer> missing;

		public Hunt(String name, Activity.Category category, double hoursToNext, double hoursToFinish, int remaining,
			int nextItemId, String nextItemName, double nextChance, boolean nextEarned, double perHour, boolean ownPace, boolean pet,
			List<Integer> missing)
		{
			this.name = name;
			this.category = category;
			this.hoursToNext = hoursToNext;
			this.hoursToFinish = hoursToFinish;
			this.remaining = remaining;
			this.nextItemId = nextItemId;
			this.nextItemName = nextItemName;
			this.nextChance = nextChance;
			this.nextEarned = nextEarned;
			this.perHour = perHour;
			this.ownPace = ownPace;
			this.pet = pet;
			this.missing = Collections.unmodifiableList(missing);
		}
	}
}

package com.codex.loginsight.data;

import java.util.Collections;
import java.util.List;
import lombok.Getter;

/** Something you can repeat to fill log slots: a boss, a raid, a casket, a minigame round. */
@Getter
public final class Activity
{
	public enum Category
	{
		COMBAT("Combat"),
		MINIGAME("Minigames"),
		OTHER("Other");

		@Getter
		private final String label;

		Category(String label)
		{
			this.label = label;
		}

		static Category of(String code)
		{
			if ("C".equals(code))
			{
				return COMBAT;
			}
			return "M".equals(code) ? MINIGAME : OTHER;
		}
	}

	private final int index;
	private final String name;
	private final Category category;
	/** Typical completions per hour on a normal account. */
	private final double perHourMain;
	/** Typical completions per hour for an ironman, who has to supply everything themselves. */
	private final double perHourIron;
	/** One-off hours before the first attempt, such as unlocking the content. */
	private final double setupHours;
	/** In table order, which matters for slots that only drop once the one before is owned. */
	private final List<Drop> drops;

	public Activity(int index, String name, Category category, double perHourMain, double perHourIron, double setupHours, List<Drop> drops)
	{
		this.index = index;
		this.name = name;
		this.category = category;
		this.perHourMain = perHourMain;
		this.perHourIron = perHourIron;
		this.setupHours = setupHours;
		this.drops = Collections.unmodifiableList(drops);
	}

	public double perHour(boolean iron)
	{
		return iron ? perHourIron : perHourMain;
	}

	/** One slot on an activity's table. */
	@Getter
	public static final class Drop
	{
		private static final int EXACT = 1;
		private static final int INDEPENDENT = 2;
		private static final int SEQUENTIAL = 4;

		private final int activityIndex;
		private final int itemId;
		/** Average attempts per drop, so 512 means 1 in 512. */
		private final double attempts;
		private final int flags;

		public Drop(int activityIndex, int itemId, double attempts, int flags)
		{
			this.activityIndex = activityIndex;
			this.itemId = itemId;
			this.attempts = attempts;
			this.flags = flags;
		}

		/** Earned after a fixed number of attempts (points, permits, a shop) rather than rolled. */
		public boolean isExact()
		{
			return (flags & EXACT) != 0;
		}

		/** Only drops once the slot listed before it on the table is owned (such as bludgeon pieces). */
		public boolean isSequential()
		{
			return (flags & SEQUENTIAL) != 0;
		}

		public boolean isIndependent()
		{
			return (flags & INDEPENDENT) != 0;
		}
	}
}

package com.codex.loginsight.data;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Getter;

/**
 * A slot's chance per kill count, possibly from several counters at once
 * (a gilded item can come from hard, elite or master caskets).
 */
@Getter
public final class ItemOdds
{
	private final List<Roll> rolls;
	/** Kill count at which the slot is guaranteed, or 0. */
	private final int guaranteedBy;

	public ItemOdds(List<Roll> rolls, int guaranteedBy)
	{
		this.rolls = Collections.unmodifiableList(rolls);
		this.guaranteedBy = guaranteedBy;
	}

	/** The counter most of this slot's chance comes from, used to label it. */
	public String mainLabel()
	{
		Roll best = rolls.get(0);
		for (Roll roll : rolls)
		{
			if (roll.chancePerCount() > best.chancePerCount())
			{
				best = roll;
			}
		}
		return best.label;
	}

	/** Chance in one kill count of the main counter, for showing "1 in N". */
	public double mainChance()
	{
		String label = mainLabel();
		double miss = 1;
		for (Roll roll : rolls)
		{
			if (roll.label.equals(label))
			{
				miss *= Math.pow(1 - roll.chance, roll.rolls);
			}
		}
		return 1 - miss;
	}

	/**
	 * The chance of still not having this slot at these counts, or -1 when none of its
	 * counters is known. Counters that are unknown count as zero.
	 */
	public double dryChance(Map<String, Integer> counters)
	{
		boolean known = false;
		double logMiss = 0;
		int main = 0;
		for (Roll roll : rolls)
		{
			Integer count = counters.get(roll.label);
			if (count == null)
			{
				continue;
			}
			known = true;
			logMiss += roll.rolls * (double) count * Math.log1p(-Math.min(roll.chance, 0.999999));
			if (roll.label.equals(mainLabel()))
			{
				main = Math.max(main, count);
			}
		}
		if (!known)
		{
			return -1;
		}
		if (guaranteedBy > 0 && main >= guaranteedBy)
		{
			return 0;
		}
		return Math.exp(logMiss);
	}

	@Getter
	public static final class Roll
	{
		private final String label;
		private final double chance;
		private final int rolls;

		public Roll(String label, double chance, int rolls)
		{
			this.label = label;
			this.chance = chance;
			this.rolls = rolls;
		}

		double chancePerCount()
		{
			return 1 - Math.pow(1 - chance, rolls);
		}
	}
}

package com.codex.loginsight.data;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The bundled tables: every activity that fills collection log slots, how often it
 * can be done in an hour and what it drops, plus each slot's odds per kill count.
 * Built by tools/build_data.py; see THIRD_PARTY_NOTICES.md for where it comes from.
 */
public final class LogData
{
	private static final String RESOURCE = "/com/codex/loginsight/codex-log.json";

	private final List<Activity> activities;
	private final Map<Integer, List<Activity.Drop>> dropsByItem;
	private final Map<Integer, ItemOdds> odds;
	private final List<String> labels;
	private final Set<Integer> pets;

	public LogData(List<Activity> activities, List<String> labels, Map<Integer, ItemOdds> odds, Set<Integer> pets)
	{
		this.activities = Collections.unmodifiableList(new ArrayList<>(activities));
		this.labels = Collections.unmodifiableList(new ArrayList<>(labels));
		this.odds = Collections.unmodifiableMap(new HashMap<>(odds));
		this.pets = Collections.unmodifiableSet(new HashSet<>(pets));
		Map<Integer, List<Activity.Drop>> byItem = new HashMap<>();
		for (Activity activity : this.activities)
		{
			for (Activity.Drop drop : activity.getDrops())
			{
				byItem.computeIfAbsent(drop.getItemId(), k -> new ArrayList<>()).add(drop);
			}
		}
		this.dropsByItem = byItem;
	}

	public static LogData load(Gson gson) throws IOException
	{
		try (InputStream in = LogData.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
			{
				return fromRaw(gson.fromJson(reader, Raw.class));
			}
		}
	}

	static LogData fromRaw(Raw raw)
	{
		List<Activity> activities = new ArrayList<>();
		for (RawActivity a : raw.activities)
		{
			List<Activity.Drop> drops = new ArrayList<>();
			int index = activities.size();
			for (double[] d : a.d)
			{
				drops.add(new Activity.Drop(index, (int) d[0], d[1], (int) d[2]));
			}
			activities.add(new Activity(index, a.n, Activity.Category.of(a.c), a.m, a.i, a.f, drops));
		}
		Map<Integer, ItemOdds> odds = new HashMap<>();
		for (Map.Entry<String, RawOdds> e : raw.odds.entrySet())
		{
			List<ItemOdds.Roll> rolls = new ArrayList<>();
			for (double[] r : e.getValue().r)
			{
				rolls.add(new ItemOdds.Roll(raw.labels.get((int) r[0]), r[1], (int) r[2]));
			}
			odds.put(Integer.parseInt(e.getKey()), new ItemOdds(rolls, e.getValue().g));
		}
		Set<Integer> pets = new HashSet<>();
		for (int id : raw.pets)
		{
			pets.add(id);
		}
		return new LogData(activities, raw.labels, odds, pets);
	}

	public List<Activity> getActivities()
	{
		return activities;
	}

	/** Every activity row that can drop this item, possibly none. */
	public List<Activity.Drop> dropsOf(int itemId)
	{
		List<Activity.Drop> drops = dropsByItem.get(itemId);
		return drops == null ? Collections.emptyList() : drops;
	}

	public Activity activity(int index)
	{
		return activities.get(index);
	}

	/** Odds per kill count, or null for slots that are bought, guaranteed or not modelled. */
	public ItemOdds odds(int itemId)
	{
		return odds.get(itemId);
	}

	/** The collection log counter names the odds refer to, such as "Vorkath kills". */
	public List<String> getLabels()
	{
		return labels;
	}

	public boolean isPet(int itemId)
	{
		return pets.contains(itemId);
	}

	static final class Raw
	{
		List<RawActivity> activities = new ArrayList<>();
		int[] pets = new int[0];
		List<String> labels = new ArrayList<>();
		Map<String, RawOdds> odds = new HashMap<>();
	}

	static final class RawActivity
	{
		String n;
		String c;
		double m;
		double i;
		double f;
		List<double[]> d = new ArrayList<>();
	}

	static final class RawOdds
	{
		List<double[]> r = new ArrayList<>();
		int g;
	}
}

package com.codex.loginsight.overlay;

import com.codex.loginsight.ui.Sigil;
import com.codex.loginsight.ui.Theme;
import java.awt.AlphaComposite;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque that rises in the game view when a new slot lands: the item, its odds,
 * the count it came at, and how lucky that was. It draws a view the plugin prepares,
 * so rendering never touches game state.
 */
public class FindPlaque extends Overlay
{
	private static final int WIDTH = 228;
	private static final int PAD = 9;
	private static final int ICON = 40;
	private static final long FADE_MS = 450;

	/** What the plaque shows. */
	public static final class View
	{
		final String name;
		final String page;
		final String odds;
		final String verdict;
		final Color color;
		final boolean pet;
		final BufferedImage icon;
		final long shownAt;
		final long durationMs;

		public View(String name, String page, String odds, String verdict, Color color, boolean pet, BufferedImage icon,
			long shownAt, long durationMs)
		{
			this.name = name;
			this.page = page;
			this.odds = odds;
			this.verdict = verdict;
			this.color = color;
			this.pet = pet;
			this.icon = icon;
			this.shownAt = shownAt;
			this.durationMs = durationMs;
		}
	}

	private volatile View view;

	public FindPlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	public void show(View view)
	{
		this.view = view;
	}

	public void clear()
	{
		view = null;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		View v = view;
		if (v == null)
		{
			return null;
		}
		long age = System.currentTimeMillis() - v.shownAt;
		if (age > v.durationMs)
		{
			view = null;
			return null;
		}
		float alpha = (float) Math.min(1, Math.min(age / (double) FADE_MS, (v.durationMs - age) / (double) FADE_MS));
		Composite old = g.getComposite();
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0, alpha)));
		Theme.smooth(g);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int lines = 2 + (v.odds == null ? 0 : 1) + (v.verdict == null ? 0 : 1);
		int textHeight = small.getHeight() + bold.getHeight() + (lines - 2) * (small.getHeight() + 1);
		int height = PAD * 2 + Math.max(ICON, textHeight);
		Color tint = v.pet ? Theme.VIOLET : Theme.GOLD;

		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 12, 12);
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 238), 0, height, Theme.alpha(Theme.INK_DEEP, 238)));
		g.fill(shape);
		double beat = 0.5 + 0.5 * Math.sin(age / 220.0);
		g.setStroke(new BasicStroke(3f));
		g.setColor(Theme.alpha(tint, (int) (40 + beat * 70)));
		g.draw(shape);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(tint, 200));
		g.draw(shape);

		// The item sits in a lit well.
		int wellX = PAD;
		int wellY = (height - ICON) / 2;
		g.setPaint(new RadialGradientPaint(wellX + ICON / 2f, wellY + ICON / 2f, ICON / 2f,
			new float[]{0f, 1f}, new Color[]{Theme.alpha(tint, 110), Theme.alpha(Theme.INK_DEEP, 220)}));
		g.fill(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		g.setColor(Theme.alpha(tint, 170));
		g.draw(new Ellipse2D.Float(wellX, wellY, ICON, ICON));
		if (v.icon != null)
		{
			g.drawImage(v.icon, wellX + (ICON - v.icon.getWidth()) / 2, wellY + (ICON - v.icon.getHeight()) / 2, null);
		}
		else
		{
			Sigil.paint(g, wellX + 8, wellY + 8, ICON - 16);
		}

		int x = PAD + ICON + 9;
		int width = WIDTH - x - PAD;
		int y = PAD + Math.max(0, (Math.max(ICON, textHeight) - textHeight) / 2);
		g.setFont(Theme.small());
		shadow(g, v.pet ? "A NEW COMPANION" : "NEW LOG SLOT", x, y + small.getAscent(), tint);
		y += small.getHeight();
		g.setFont(Theme.title());
		shadow(g, clip(v.name, bold, width), x, y + bold.getAscent(), Theme.GOLD_BRIGHT);
		y += bold.getHeight();
		g.setFont(Theme.small());
		if (v.odds != null)
		{
			shadow(g, clip(v.odds, small, width), x, y + small.getAscent(), Theme.TEXT_MUTED);
			y += small.getHeight() + 1;
		}
		if (v.verdict != null)
		{
			shadow(g, clip(v.verdict, small, width), x, y + small.getAscent(), v.color);
		}
		g.setComposite(old);
		return new Dimension(WIDTH, height);
	}

	private static void shadow(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	private static String clip(String text, FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		String ellipsis = "...";
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + ellipsis) > width)
		{
			end--;
		}
		return text.substring(0, end) + ellipsis;
	}
}

package com.codex.loginsight.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.loginsight.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private final String text;
	private final boolean primary;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.primary = primary;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire)
				{
					action.run();
				}
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Luck;
import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.geom.Path2D;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/**
 * The crest at the top of the panel: a ring for the whole log, the slot count, and
 * three ledgers for finished pages, luck and the hours still ahead.
 */
public class Crest extends JPanel
{
	private final ProgressRing ring = new ProgressRing(70, 7f);
	private final JLabel title = Ui.label("Log Insight", Theme.title(), Theme.GOLD_BRIGHT);
	private final JLabel slots = Ui.label("Log in to read your log", Theme.small(), Theme.TEXT_MUTED);
	private final Ledger pages = new Ledger("Pages done", true);
	private final Ledger luck = new Ledger("Luck", false);
	private final Ledger left = new Ledger("Hours left", false);
	private Color glow = Theme.GOLD_DIM;

	public Crest()
	{
		super(new BorderLayout(10, 0));
		setOpaque(false);
		setBorder(new EmptyBorder(12, 10, 12, 10));

		JPanel ringHolder = new JPanel(new BorderLayout());
		ringHolder.setOpaque(false);
		ringHolder.add(ring, BorderLayout.NORTH);
		add(ringHolder, BorderLayout.WEST);

		JPanel right = new JPanel();
		right.setOpaque(false);
		right.setLayout(new BoxLayout(right, BoxLayout.Y_AXIS));
		title.setAlignmentX(LEFT_ALIGNMENT);
		slots.setAlignmentX(LEFT_ALIGNMENT);
		right.add(title);
		right.add(slots);
		JPanel ledgers = new JPanel(new GridLayout(3, 1, 0, 2));
		ledgers.setOpaque(false);
		ledgers.setBorder(new EmptyBorder(4, 0, 0, 0));
		ledgers.add(pages);
		ledgers.add(luck);
		ledgers.add(left);
		ledgers.setAlignmentX(LEFT_ALIGNMENT);
		right.add(ledgers);
		add(right, BorderLayout.CENTER);
		ring.setCaption("logged");
		ring.setProgress(0, false, false);
	}

	public void update(Report report, String playerName)
	{
		if (!report.isLoggedIn())
		{
			title.setText("Log Insight");
			slots.setText("Log in to read your log");
			ring.setProgress(0, false, true);
			pages.set("-", 0, Theme.TEXT);
			luck.set("-", -1, Theme.TEXT);
			left.set("-", -1, Theme.TEXT);
			glow = Theme.GOLD_DIM;
			repaint();
			return;
		}
		int owned = report.owned();
		int total = report.total();
		title.setText(playerName == null ? "Log Insight" : playerName);
		slots.setText(total <= 0 ? "Reading the log..." : Format.count(owned) + " / " + Format.count(total) + " slots");
		ring.setProgress(total <= 0 ? 0 : owned / (double) total, total > 0 && owned >= total, true);
		pages.set(report.getPagesComplete() + "/" + report.getPagesTotal(),
			report.getPagesTotal() == 0 ? 0 : report.getPagesComplete() / (double) report.getPagesTotal(), Theme.TEXT);
		Luck l = report.getLuck();
		if (l == null)
		{
			luck.set("Unread", -1, Theme.TEXT_MUTED);
			glow = Theme.GOLD_DIM;
		}
		else
		{
			Color c = Theme.luck(l.verdict());
			luck.set(l.verdict().getLabel(), -1, c);
			glow = Theme.mix(Theme.GOLD_DIM, c, 0.45);
		}
		left.set(Format.hours(report.getHoursLeft()), -1, Theme.TEXT);
		left.setToolTipText(report.isIronRates() ? "At ironman rates" : "At typical rates, or your own pace where Log Insight has learned it");
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, glow, 0.2), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// Gilt rule along the bottom with a small diamond at its centre.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
		super.paintComponent(graphics);
	}

	/** One labelled value, with a hairline bar under it when the value is a share of something. */
	private static final class Ledger extends JPanel
	{
		private final JLabel value = Ui.label("-", Theme.small(), Theme.TEXT);
		private final ProgressBar bar;

		Ledger(String label, boolean withBar)
		{
			super(new BorderLayout(0, 1));
			setOpaque(false);
			JPanel line = new JPanel(new BorderLayout());
			line.setOpaque(false);
			line.add(Ui.label(label, Theme.small(), Theme.TEXT_MUTED), BorderLayout.WEST);
			line.add(value, BorderLayout.EAST);
			add(line, BorderLayout.CENTER);
			bar = withBar ? new ProgressBar(3) : null;
			if (bar != null)
			{
				add(bar, BorderLayout.SOUTH);
			}
			setPreferredSize(new Dimension(10, 17));
		}

		void set(String text, double share, Color color)
		{
			value.setText(text);
			value.setForeground(color);
			if (bar != null)
			{
				bar.setProgress(Math.max(0, share), share >= 1, true);
			}
		}
	}
}

package com.codex.loginsight.ui;

import com.codex.loginsight.core.Report;
import java.awt.BorderLayout;
import java.awt.FlowLayout;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.function.Consumer;
import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;

/** Every page of the log, grouped by tab, each with its progress, kill count and luck. */
final class FoliosView
{
	private FoliosView()
	{
	}

	static StackPanel build(Report report, String filter, Consumer<String> openPage)
	{
		StackPanel stack = new StackPanel(5, 8);
		if (!report.isLoggedIn())
		{
			stack.add(Rows.note("Log in to see your log page by page.", 190));
			return stack;
		}
		if (report.getPages().isEmpty())
		{
			stack.add(Rows.note("Reading the log's pages from the game...", 190));
			return stack;
		}
		String needle = filter == null ? "" : filter.trim().toLowerCase(Locale.ENGLISH);
		Map<String, List<Report.PageReport>> byTab = new LinkedHashMap<>();
		for (Report.PageReport page : report.getPages())
		{
			if (needle.isEmpty() || page.getName().toLowerCase(Locale.ENGLISH).contains(needle) || matchesItem(page, needle))
			{
				byTab.computeIfAbsent(page.getTab(), k -> new ArrayList<>()).add(page);
			}
		}
		if (byTab.isEmpty())
		{
			stack.add(Rows.note("No page or slot matches \"" + filter.trim() + "\".", 190));
			return stack;
		}
		for (Map.Entry<String, List<Report.PageReport>> tab : byTab.entrySet())
		{
			int done = 0;
			for (Report.PageReport page : tab.getValue())
			{
				done += page.isComplete() ? 1 : 0;
			}
			stack.add(new SectionHeader(tab.getKey(), done + "/" + tab.getValue().size()));
			for (Report.PageReport page : tab.getValue())
			{
				stack.add(row(page).onClick(() -> openPage.accept(page.getName())));
			}
		}
		return stack;
	}

	private static boolean matchesItem(Report.PageReport page, String needle)
	{
		for (Report.ItemReport item : page.getItems())
		{
			if (item.getName().toLowerCase(Locale.ENGLISH).contains(needle))
			{
				return true;
			}
		}
		return false;
	}

	static Card row(Report.PageReport page)
	{
		Card card = new Card(new BorderLayout(0, 3));
		card.setBorder(new EmptyBorder(6, 10, 7, 10));
		if (page.isComplete())
		{
			card.accent(Theme.GREEN);
		}
		else if (page.getLuck() != null)
		{
			card.accent(Theme.luck(page.getLuck().verdict()));
		}

		JPanel line = new JPanel(new BorderLayout(6, 0));
		line.setOpaque(false);
		line.add(Ui.label(page.getName(), Theme.body(), page.isComplete() ? Theme.GOLD_BRIGHT : Theme.TEXT), BorderLayout.CENTER);
		line.add(Ui.label(page.getOwned() + "/" + page.getTotal(), Theme.small(), page.isComplete() ? Theme.GREEN : Theme.TEXT_MUTED),
			BorderLayout.EAST);
		card.add(line, BorderLayout.NORTH);

		ProgressBar bar = new ProgressBar(4);
		bar.setProgress(page.progress(), page.isComplete(), false);
		card.add(bar, BorderLayout.CENTER);

		JPanel meta = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
		meta.setOpaque(false);
		if (page.getLuck() != null && !page.isComplete())
		{
			meta.add(new Pill(page.getLuck().verdict().getLabel(), Theme.luck(page.getLuck().verdict())));
		}
		if (page.getCount() >= 0)
		{
			meta.add(Ui.label(Format.count(page.getCount()) + " kc", Theme.small(), Theme.TEXT_MUTED));
		}
		if (!page.isComplete() && Double.isFinite(page.getHoursToNext()))
		{
			meta.add(Ui.label("next " + Format.about(page.getHoursToNext()), Theme.small(), Theme.TEXT_FAINT));
		}
		if (meta.getComponentCount() > 0)
		{
			((FlowLayout) meta.getLayout()).setHgap(5);
			card.add(meta, BorderLayout.SOUTH);
		}
		return card;
	}
}

package com.codex.loginsight.ui;

/** Turns hours, odds and counts into the short phrases the panel uses. */
public final class Format
{
	private Format()
	{
	}

	/** "<1m", "45m", "3h 12m", "120h" or "8,420h"; "-" when it cannot be estimated. */
	public static String hours(double hours)
	{
		if (Double.isNaN(hours) || Double.isInfinite(hours) || hours < 0)
		{
			return "-";
		}
		double minutes = hours * 60;
		if (minutes < 1)
		{
			return "<1m";
		}
		if (minutes < 60)
		{
			return Math.round(minutes) + "m";
		}
		if (hours < 10)
		{
			long h = (long) hours;
			long m = Math.round((hours - h) * 60);
			if (m == 60)
			{
				h++;
				m = 0;
			}
			return m == 0 ? h + "h" : h + "h " + m + "m";
		}
		return String.format("%,dh", Math.round(hours));
	}

	/** "about 3h", or "under 1m" when it is that short. */
	public static String about(double hours)
	{
		String text = hours(hours);
		if (text.startsWith("<"))
		{
			return "under " + text.substring(1);
		}
		return "-".equals(text) ? text : "~" + text;
	}

	/** "1/512", or "1/3.4" for common drops; "-" when unknown. */
	public static String chance(double chance)
	{
		if (chance <= 0 || Double.isNaN(chance))
		{
			return "-";
		}
		double in = 1 / chance;
		if (in < 1.05)
		{
			return "Always";
		}
		if (in < 10)
		{
			return String.format("1/%.1f", in);
		}
		return String.format("1/%,d", Math.round(in));
	}

	public static String count(long value)
	{
		return String.format("%,d", value);
	}

	/** Whole percent, with "<1%" and ">99%" at the ends so rare cases never read as 0 or 100. */
	public static String percent(double share)
	{
		if (share <= 0)
		{
			return "0%";
		}
		if (share < 0.01)
		{
			return "<1%";
		}
		if (share > 0.99 && share < 1)
		{
			return ">99%";
		}
		return Math.round(share * 100) + "%";
	}

	/** "just now", "5m ago", "3h ago", "2d ago". */
	public static String ago(long then, long now)
	{
		long seconds = Math.max(0, (now - then) / 1000);
		if (seconds < 60)
		{
			return "just now";
		}
		if (seconds < 3600)
		{
			return seconds / 60 + "m ago";
		}
		if (seconds < 86400)
		{
			return seconds / 3600 + "h ago";
		}
		return seconds / 86400 + "d ago";
	}

	/** "Vorkath kills" to "Vorkath", for compact lines that already say "kc". */
	public static String counterName(String label)
	{
		if (label == null)
		{
			return "";
		}
		return label.replaceAll("(?i) (kills|completions|completion count|opened|completed)$", "");
	}

	/** An activity name for a card title: the parenthetical detail moves to the tooltip. */
	public static String activity(String name)
	{
		String shortName = name.replaceAll("\\s*\\([^)]*\\)", "").trim();
		return shortName.isEmpty() ? name : Character.toUpperCase(shortName.charAt(0)) + shortName.substring(1);
	}
}

package com.codex.loginsight.ui;

import java.awt.AlphaComposite;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/** An item picture sitting in a small dark well, used at the start of list rows. */
class IconBadge extends JComponent
{
	private final boolean owned;
	private BufferedImage image;

	IconBadge(int itemId, ItemIcons icons, boolean owned)
	{
		this.owned = owned;
		Dimension d = new Dimension(28, 26);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		setOpaque(false);
		if (icons != null && itemId > 0)
		{
			image = icons.icon(itemId, this::repaint);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fill(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		g.setColor(Theme.alpha(owned ? Theme.GOLD : Theme.STROKE, owned ? 120 : 200));
		g.draw(new Ellipse2D.Float(1, 1, w - 2, h - 2));
		if (image != null)
		{
			int iw = Math.min(image.getWidth(), 36);
			int ih = Math.min(image.getHeight(), 32);
			double scale = Math.min((w - 2) / (double) iw, (h - 2) / (double) ih);
			int dw = (int) Math.round(iw * scale);
			int dh = (int) Math.round(ih * scale);
			if (!owned)
			{
				g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.45f));
			}
			g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
		}
		g.dispose();
	}
}

